-- =====================================================================
-- fund_demo —— 智能问数（Text-to-SQL）演示库
-- 由 scripts/gen_fund_demo_sql.py 自动生成，随机种子 20261031
--
-- ⚠️ 数据声明：本文件中的基金净值、份额、订单、渠道折扣、金额
--    全部为**虚构测试数据**，仅用于验证 Text-to-SQL 链路，
--    不代表任何真实基金的历史业绩或真实交易。
--
-- 用法（任选其一）：
--   1) 宿主机：  mysql -h 127.0.0.1 -P 3306 -u root -p < fund_demo.sql
--   2) 容器内：  docker exec -i docker-mysql-1 mysql -uroot -p'<密码>' < fund_demo.sql
--   3) 客户端：  用 Navicat / DBeaver 打开本文件整体执行
--
-- 幂等：可重复执行，会先 DROP TABLE 再重建（不会动其他库）。
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `fund_demo` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `fund_demo`;

DROP TABLE IF EXISTS `fund_order`;
DROP TABLE IF EXISTS `fund_redeem_rule`;
DROP TABLE IF EXISTS `fund_fee_discount`;
DROP TABLE IF EXISTS `fund_channel`;
DROP TABLE IF EXISTS `fund_nav`;
DROP TABLE IF EXISTS `fund_product`;

-- ---------------------------------------------------------------------
-- 1. 基金产品表
-- ---------------------------------------------------------------------
CREATE TABLE `fund_product` (
  `fund_code`           VARCHAR(6)     NOT NULL COMMENT '基金代码',
  `fund_name`           VARCHAR(64)    NOT NULL COMMENT '基金简称',
  `fund_type`           VARCHAR(16)    NOT NULL COMMENT '基金类型：混合型/债券型/指数型/QDII/货币型',
  `risk_level`          TINYINT        NOT NULL COMMENT '风险等级 1-5，数字越大风险越高',
  `manage_fee_rate`     DECIMAL(6,2)   NOT NULL COMMENT '年管理费率，单位 %',
  `purchase_fee_rate`   DECIMAL(6,2)   NOT NULL COMMENT '申购费率基准，单位 %；渠道可打折，见 fund_fee_discount',
  `min_purchase_amount` DECIMAL(12,2)  NOT NULL COMMENT '起购金额，单位元',
  `status`              VARCHAR(16)    NOT NULL COMMENT '销售状态：开放申购/暂停申购/开放赎回',
  `established_date`    DATE           NOT NULL COMMENT '基金成立日',
  `latest_nav`          DECIMAL(8,4)   NOT NULL COMMENT '最新单位净值（= fund_nav 中最新交易日的 unit_nav）',
  `latest_nav_date`     DATE           NOT NULL COMMENT '最新净值日期',
  `fund_manager`        VARCHAR(32)    NOT NULL COMMENT '基金经理',
  `company`             VARCHAR(64)    NOT NULL COMMENT '基金公司',
  PRIMARY KEY (`fund_code`),
  KEY `idx_type` (`fund_type`),
  KEY `idx_risk` (`risk_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='基金产品';


-- ---------------------------------------------------------------------
-- 2. 基金净值表（逐交易日，已剔除周末与国庆休市 2026-10-01~10-07）
-- ---------------------------------------------------------------------
CREATE TABLE `fund_nav` (
  `fund_code`    VARCHAR(6)   NOT NULL COMMENT '基金代码',
  `nav_date`     DATE         NOT NULL COMMENT '净值日期（交易日）',
  `unit_nav`     DECIMAL(8,4) NOT NULL COMMENT '单位净值；货币基金恒为 1.0000',
  `acc_nav`      DECIMAL(8,4) NOT NULL COMMENT '累计净值',
  `daily_return` DECIMAL(8,4) NOT NULL COMMENT '日涨跌幅，单位 %；货币基金为 0',
  PRIMARY KEY (`fund_code`,`nav_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='基金净值';


-- ---------------------------------------------------------------------
-- 3. 销售渠道表
-- ---------------------------------------------------------------------
CREATE TABLE `fund_channel` (
  `channel_code`       VARCHAR(8)  NOT NULL COMMENT '渠道编码',
  `channel_name`       VARCHAR(64) NOT NULL COMMENT '渠道名称',
  `channel_type`       VARCHAR(16) NOT NULL COMMENT '渠道类型：直销/银行代销/第三方代销',
  `settle_days`        TINYINT     NOT NULL COMMENT '确认天数 T+N',
  `support_auto_invest` VARCHAR(2) NOT NULL COMMENT '是否支持定投：是/否',
  `status`             VARCHAR(8)  NOT NULL COMMENT '渠道状态：正常/下线',
  PRIMARY KEY (`channel_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='销售渠道';


-- ---------------------------------------------------------------------
-- 4. 渠道申购费率折扣表（按 渠道 × 基金类型 定价）
-- ---------------------------------------------------------------------
CREATE TABLE `fund_fee_discount` (
  `channel_code`   VARCHAR(8)   NOT NULL COMMENT '渠道编码',
  `fund_type`      VARCHAR(16)  NOT NULL COMMENT '基金类型',
  `discount_rate`  DECIMAL(4,2) NOT NULL COMMENT '折扣率：1.00=不打折，0.10=1折，0.00=免申购费',
  `effective_date` DATE         NOT NULL COMMENT '生效日期',
  `remark`         VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`channel_code`,`fund_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='渠道申购费率折扣';


-- ---------------------------------------------------------------------
-- 5. 赎回费率分档表（按 基金类型 × 持有天数区间）
-- ---------------------------------------------------------------------
CREATE TABLE `fund_redeem_rule` (
  `id`              INT          NOT NULL AUTO_INCREMENT,
  `fund_type`       VARCHAR(16)  NOT NULL COMMENT '基金类型',
  `holding_days_min` INT         NOT NULL COMMENT '持有天数下限（含）',
  `holding_days_max` INT         NOT NULL COMMENT '持有天数上限（含）；9999 表示无上限',
  `redeem_fee_rate` DECIMAL(6,2) NOT NULL COMMENT '赎回费率，单位 %',
  `remark`          VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_type` (`fund_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='赎回费率分档';


-- ---------------------------------------------------------------------
-- 6. 交易订单表（640 笔，2026-09-01 ~ 2026-10-31）
-- ---------------------------------------------------------------------
CREATE TABLE `fund_order` (
  `id`           BIGINT        NOT NULL AUTO_INCREMENT,
  `order_no`     VARCHAR(32)   NOT NULL COMMENT '订单号',
  `customer_id`  VARCHAR(16)   NOT NULL COMMENT '客户号',
  `fund_code`    VARCHAR(6)    NOT NULL COMMENT '基金代码',
  `channel_code` VARCHAR(8)    NOT NULL COMMENT '渠道编码',
  `order_type`   VARCHAR(8)    NOT NULL COMMENT '业务类型：申购/赎回/定投',
  `amount`       DECIMAL(14,2) NOT NULL COMMENT '交易金额，单位元',
  `shares`       DECIMAL(16,4) NOT NULL COMMENT '交易份额',
  `order_date`   DATE          NOT NULL COMMENT '下单日期',
  `confirm_date` DATE          NOT NULL COMMENT '确认日期',
  `status`       VARCHAR(8)    NOT NULL COMMENT '订单状态：已确认/待确认/已撤单',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_date` (`order_date`),
  KEY `idx_fund` (`fund_code`),
  KEY `idx_channel` (`channel_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='基金交易订单';


-- ---------------------------------------------------------------------
-- 7. 只读账号（供 ExeSQL / Text-to-SQL 使用）
--    mysql_native_password 是为了兼容部分 Go 驱动的 caching_sha2 握手问题；
--    若你的 MySQL 已禁用该插件，把下面这句换成普通 IDENTIFIED BY 即可。
-- ---------------------------------------------------------------------
CREATE USER IF NOT EXISTS 'fund_ro'@'%' IDENTIFIED WITH mysql_native_password BY 'FundDemo_2026';
ALTER USER 'fund_ro'@'%' IDENTIFIED WITH mysql_native_password BY 'FundDemo_2026';
GRANT SELECT ON `fund_demo`.* TO 'fund_ro'@'%';
FLUSH PRIVILEGES;

SET FOREIGN_KEY_CHECKS = 1;

